package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

// Encode normalizes the plaintext (lower-cased, spaces and punctuation
// removed), lays it out in a rectangle with c columns and r rows where
// r*c >= len, c >= r and c-r <= 1, then reads the rectangle down the
// columns, left to right. The result is emitted as c chunks of r
// characters separated by spaces, with trailing spaces padding the last
// chunks of a ragged rectangle.
func Encode(pt string) string {
	var msg []rune
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			msg = append(msg, unicode.ToLower(r))
		}
	}

	n := len(msg)
	if n == 0 {
		return ""
	}

	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := int(math.Ceil(float64(n) / float64(c)))

	var chunks []string
	for col := 0; col < c; col++ {
		var chunk strings.Builder
		chunk.Grow(r)
		for row := 0; row < r; row++ {
			if idx := row*c + col; idx < n {
				chunk.WriteRune(msg[idx])
			} else {
				chunk.WriteRune(' ')
			}
		}
		chunks = append(chunks, chunk.String())
	}

	return strings.Join(chunks, " ")
}
